#include <stdio.h>


int main(void)
{
    struct Node { int value; struct Node *next; };
    struct Node a = {4, NULL};
    struct Node b = {9, &a};
    struct Node *top = &b;
    top = top->next;
    printf("%d\n", top->value);
    return 0;
}

#include <stdio.h>


int main(void)
{
    struct Node { struct Node *next; };
    struct Node node = {NULL};
    struct Node *top = &node;
    top = top->next;
    printf("%d\n", top == NULL);
    return 0;
}
